#!/bin/bash
# One source for the TV measures: Werkzeuge/tv-spec.json (Apple TV points; Android TV dp = pt / 2).
#
#   Werkzeuge/gen-tv-spec.sh           write Sources/tvOS/TVSpec.swift and Android/.../tv/TvSpec.kt
#   Werkzeuge/gen-tv-spec.sh --check   fail if a generated file is stale, or a guarded view repeats a spec number
#
# Both sides read the constants and never type a number of their own for what is in the spec. The
# check runs in Werkzeuge/check.sh.
set -eu
cd "$(dirname "$0")/.."
exec python3 -I - "$@" <<'PY'
import json, re, sys, pathlib

root = pathlib.Path.cwd()
spec = json.loads((root / "Werkzeuge/tv-spec.json").read_text())
SWIFT = root / "Sources/tvOS/TVSpec.swift"
KOTLIN = root / "Android/phone/src/main/java/de/paulherter/swiftly/tv/TvSpec.kt"

def num(v):
    s = ("%g" % v)
    return s

def swift_name(k): return k
def dp(v):
    d = v / 2
    return ("%g" % d)

def camel_up(s): return s[0].upper() + s[1:]

def make_swift():
    o = ["// Generated by Werkzeuge/gen-tv-spec.sh from Werkzeuge/tv-spec.json. Do not edit.",
         "import CoreGraphics", "", "/// The TV measures, shared with Android TV (dp = pt / 2).", "enum TVSpec {"]
    for k, v in spec["lengths"].items(): o.append(f"    static let {k}: CGFloat = {num(v)}")
    o.append("")
    for k, v in spec.get("counts", {}).items(): o.append(f"    static let {k} = {int(v)}")
    o.append("")
    for k, v in spec["scales"].items(): o.append(f"    static let {k}: CGFloat = {num(v)}")
    o.append("")
    for k, v in spec["opacities"].items(): o.append(f"    static let {k}Opacity: Double = {num(v)}")
    o.append("")
    for k, v in spec["durations"].items(): o.append(f"    static let {k}Duration: Double = {num(v)}")
    o.append("")
    for k, v in spec["curves"].items(): o.append(f"    static let {k}Curve: (Double, Double, Double, Double) = ({', '.join(num(x) for x in v)})")
    o.append("")
    for k, v in spec["margins"].items(): o.append(f"    static let {k}Margin: CGFloat = {num(v)}")
    o.append("}")
    return "\n".join(o) + "\n"

def make_kotlin():
    o = ["// Generated by Werkzeuge/gen-tv-spec.sh from Werkzeuge/tv-spec.json. Do not edit.",
         "package de.paulherter.swiftly.tv", "",
         "import androidx.compose.animation.core.CubicBezierEasing",
         "import androidx.compose.ui.unit.dp", "",
         "/** The TV measures, shared with Apple TV (dp = pt / 2). */", "object TvSpec {"]
    for k, v in spec["lengths"].items(): o.append(f"    val {k} = {dp(v)}.dp")
    o.append("")
    for k, v in spec.get("counts", {}).items(): o.append(f"    const val {k} = {int(v)}")
    o.append("")
    for k, v in spec["scales"].items(): o.append(f"    const val {k} = {num(v)}f")
    o.append("")
    for k, v in spec["opacities"].items(): o.append(f"    const val {k}Opacity = {num(v)}f")
    o.append("")
    for k, v in spec["durations"].items(): o.append(f"    const val {k}Ms = {int(round(v * 1000))}")
    o.append("")
    for k, v in spec["curves"].items(): o.append(f"    val {k}Curve = CubicBezierEasing({', '.join(num(x) + 'f' for x in v)})")
    o.append("")
    for k, v in spec["margins"].items(): o.append(f"    val {k}Margin = {dp(v)}f  // dp")
    o.append("}")
    return "\n".join(o) + "\n"

outputs = {SWIFT: make_swift(), KOTLIN: make_kotlin()}

if "--check" not in sys.argv:
    for p, t in outputs.items():
        p.write_text(t); print("written", p.relative_to(root))
    sys.exit(0)

bad = []
for p, t in outputs.items():
    if not p.exists() or p.read_text() != t:
        bad.append(f"{p.relative_to(root)} does not match tv-spec.json (run Werkzeuge/gen-tv-spec.sh)")

# Guarded views: no literal of a spec number. Lengths below 13 dp are too common to mean anything.
lengths = sorted({dp(v) for v in spec["lengths"].values() if v / 2 >= 13})
ms = sorted({int(round(v * 1000)) for k, v in spec["durations"].items() if v >= 0.1})
scales = [num(v) for k, v in spec["scales"].items() if k.startswith("focusMagnifier")]
for f in spec["guarded"]["kotlin"]:
    path = root / f
    for n, line in enumerate(path.read_text().splitlines(), 1):
        if "tv-spec: unrelated" in line: continue
        code = line.split("//")[0]
        for L in lengths:
            if re.search(r"(?<![\w.])" + re.escape(L) + r"(\.0)?\.dp\b", code): bad.append(f"{f}:{n}: literal {L}.dp is in tv-spec.json")
        for m in ms:
            if re.search(r"tween\(\s*" + str(m) + r"\b", code): bad.append(f"{f}:{n}: literal tween({m}) is in tv-spec.json")
        for s in scales:
            if re.search(r"(?<![\w.])" + re.escape(s) + r"0?f\b", code): bad.append(f"{f}:{n}: literal {s}f is in tv-spec.json")
for f in spec["guarded"]["swift"]:
    path = root / f
    for n, line in enumerate(path.read_text().splitlines(), 1):
        if "tv-spec: unrelated" in line: continue
        code = line.split("//")[0]
        for v in sorted({num(v) for v in spec["lengths"].values() if v >= 26}):
            if re.search(r"(?<![\w.])" + re.escape(v) + r"(\.0)?\b(?!\s*[%x])", code) and re.search(r"padding|frame|spacing|cornerRadius|size:", code):
                bad.append(f"{f}:{n}: literal {v} is in tv-spec.json")
if bad:
    print("\n".join(bad)); sys.exit(1)
print("tv-spec: generated files match, guarded views clean")
PY
